import json,sys,collections; sys.path.insert(0,'.')
from bench.agentpii5.schema import case_v5_from_json
fold=lambda s: s.casefold().replace('ё','е')
rows=json.load(open('bench/agentpii5/corpus.v5.json'))['corpus']
