        for i in c.base.pii:
            if i.identity==fid and i.type=='NAME' and {fold(w) for w in i.value.split() if len(w)>3} & own:
                clash.append((c.base.id,fid,i.value))
print('cases with one value under two identities:',len(dupe))
print('foreign identity == the customer:',clash)
