cross=[]; seedmem=0
for r in rows:
    c=case_v5_from_json(r); it={i.id:i for i in c.base.pii}; idx={h.hop_index:h for h in c.hops}
    for h in c.hops:
        if h.kind=='OUT' and h.source_hop!=-1:
            s=idx.get(h.source_hop)
            if s and s.kind=='IN' and s.owner=='tool' and s.tool_name!=h.tool_name and h.item_id!=s.item_id:
                cross.append((c.base.id,h.path,it[h.item_id].value,'<-',it[s.item_id].value))
        if h.kind=='IN' and h.owner=='memory' and it[h.item_id].where.kind!='message': seedmem+=1
print('cross-item chain transitions:',len(cross), cross[:3])
print('IN/memory hops on a seed item:',seedmem)
